def site(name,state,phase,evidence,date,src,locator,status='checked passage',gap='',chapters='03, 06'):
    R.append(dict(id=f'NE-SITE-{len(R)+1:03}',name=name,state=state,reported_classification=phase,evidence=evidence,dating=date,source_id=src,locator=locator,review_status=status,remaining_check=gap,chapter_links=chapters))
